import sys

def find_reversible_subsequence(n, cards):
    # Find the longest increasing subsequence (LIS)
    lis = []
    for card in cards:
        pos = binary_search(lis, card)
        if pos < len(lis):
            lis[pos] = card
        else:
            lis.append(card)

    # If the entire array is already sorted, return "impossible"
    if len(lis) == n:
        return "impossible"

    # Find the point where the LIS stops and the rest starts
    lis_end = len(lis)
    for i in range(n):
        if cards[i] != lis[i]:
            lis_end = i
            break

    # Find the point where the reverse subsequence should start
    for j in range(n - 1, -1, -1):
        if cards[j] != lis[-(n - j)]:
            break

    # Check if reversing the subsequence from lis_end to j+1 sorts the array
    reversed_subseq = cards[lis_end:j+1][::-1]
    if cards[:lis_end] + reversed_subseq + cards[j+1:] == sorted(cards):
        return f"{lis_end + 1} {j + 1}"

    return "impossible"

def binary_search(lis, card):
    low, high = 0, len(lis)
    while low < high:
        mid = (low + high) // 2
        if lis[mid] < card:
            low = mid + 1
        else:
            high = mid
    return low

