def find_inversions(arr):
    n = len(arr)
    inversions = []
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                inversions.append((i, j))
    return inversions

def can_restore_order_by_reversing_one_subsequence(arr):
    inversions = find_inversions(arr)
    if len(inversions) != 2:
        return "impossible"

    i1, j1 = inversions[0]
