import sys

def find_reversible_subsequence(n, cards):
    # Function to find the length of the longest increasing subsequence
    def lis(arr):
        dp = [1] * n
        for i in range(1, n):
            for j in range(i):
                if arr[i] >= arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    # Function to find the length of the longest decreasing subsequence
    def lds(arr):
        dp = [1] * n
        for i in range(n-2, -1, -1):
            for j in range(i+1, n):
                if arr[i] >= arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return max(dp)

    # Calculate LIS and LDS
    lis_length = lis(cards)
    lds_length = lds(cards)

    # Check if reversing a subsequence can sort the array
    if lis_length + lds_length - 1 == n:
        # Find the end of LIS and start of LDS
        end_lis = 0
        for i in range(n):
            if lis(cards[:i+1]) == i + 1:
                end_lis = i

        start_lds = n - 1
        for i in range(n-1, -1, -1):
            if lds(cards[i:]) == n - i:
                start_lds = i
                break

        # Return the 1-based indices of the subsequence to reverse
        return [end_lis + 2, start_lds + 1]

    return "impossible"

